{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create or replace Table MEDMONGERS_DB.MAPLEMONK.MEDMONGERS_UNICOMMERCE_FACT_ITEMS AS SELECT * FROM ( SELECT \"Shipping Address Pincode\" AS shipping_pincode, \"Billing Address Pincode\" AS billing_pincode, \"Channel Name\" AS marketplace, \"Channel Name\" AS source, \"Display Order Code\" AS order_id, \"Display Order Code\" AS reference_code, \"Shipping Address Phone\" AS phone, \"Billing Address Name\" AS name, \"Notification Email\" AS email, UPPER(category) AS category, TO_VARCHAR(TRY_TO_TIMESTAMP(NULLIF(UPDATED, \'\')), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS SHIPPING_LAST_UPDATE_DATE, \"Shipping provider\" AS Shipping_Provider, \"Item SKU Code\" AS sku, \"Seller SKU Code\" AS Marketplace_sku, case when upper(marketplace) like \'%PHARMEASY%\' then LTRIM(\"Channel Product Id\", \'0\') else \"Channel Product Id\" end AS product_id, COALESCE(\"Item Type Name\", \"SKU Name\") AS product_name, CURRENCY, COALESCE(\"Shipping Address City\", \"Billing Address City\") AS city, COALESCE(\"Shipping Address State\", \"Billing Address State\") AS state, CASE WHEN \"Sale Order Status\" NOT IN (\'COMPLETE\',\'CANCELLED\') AND \"Shipping Package Status Code\" IS NULL THEN \'UNFULFILLABLE\' ELSE \"Sale Order Status\" END AS order_status, \"Invoice Code\" AS invoice_code, TO_VARCHAR(TRY_TO_TIMESTAMP(NULLIF(\"Invoice Created\", \'\')), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS invoice_date, TO_VARCHAR(TRY_TO_TIMESTAMP(NULLIF(\"Order Date as dd/mm/yyyy hh:MM:ss\", \'\')), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS order_date, TO_VARCHAR(TRY_TO_TIMESTAMP(NULLIF(\"Shipping Package Creation Date\", \'\')), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS shipping_package_creation_date, TRY_TO_DOUBLE(\"Shipping Charges\") AS shipping_price, 1 AS suborder_quantity, TRY_TO_DOUBLE(discount) AS discount, TRY_TO_DOUBLE(\"Tax Value\") AS tax, TRY_TO_DOUBLE(\"Selling Price\") AS selling_price, \"Shipping Package Code\" AS shippingPackageCode, \"Shipping Package Status Code\" AS shippingPackageStatus, \"Sale Order Item Code\" AS SaleOrderItemCode, \"Sale Order Item Code\" AS Sales_Order_Item_ID, \"Tracking Number\" AS AWB, FACILITY AS Warehouse_Name, CASE WHEN COD = \'0\' THEN \'Prepaid\' ELSE \'COD\' END AS Payment_Mode, CASE WHEN COD = \'0\' THEN \'Prepaid\' ELSE \'COD\' END AS Payment_Method, \"Shipping Courier\" AS Courier, \"Shipping Courier Status\" AS shipping_status, \"Shipping Tracking Status\" AS shipping_tracking_status, 1 AS shippedQuantity, TO_VARCHAR(TRY_TO_TIMESTAMP(NULLIF(\"Packing Time\", \'\')), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS packing_date, TO_VARCHAR(TRY_TO_TIMESTAMP(NULLIF(\"Dispatch Date\", \'\')), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS dispatch_date, TO_VARCHAR(TRY_TO_TIMESTAMP(NULLIF(\"EWayBill Date\", \'\')), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS ewaybill_date, TO_VARCHAR(TRY_TO_TIMESTAMP(NULLIF(\"Delivery Time\", \'\')), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS delivery_date, TO_VARCHAR(TRY_TO_TIMESTAMP(NULLIF(\"Return Date\", \'\')), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS return_date, TO_VARCHAR(TRY_TO_TIMESTAMP(NULLIF(\"Reverse Pickup Created Date\", \'\')), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS reverse_pickup_date, TO_VARCHAR(TRY_TO_TIMESTAMP(NULLIF(\"Fulfillment TAT\", \'\')), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS fulfillment_tat, \"Reverse Pickup Code\" AS reverse_pickup_code, \"Return Remarks\" AS return_remarks, \"Reverse Pickup Reason\" AS reverse_pickup_reason, CASE WHEN \"Return Date\" IS NOT NULL AND TRIM(\"Return Date\") <> \'\' AND LOWER(TRIM(\"Return Date\")) <> \'null\' THEN 1 ELSE 0 END AS return_flag, CASE WHEN \"Return Date\" IS NOT NULL AND TRIM(\"Return Date\") <> \'\' AND LOWER(TRIM(\"Return Date\")) <> \'null\' THEN 1 ELSE 0 END AS return_quantity, CASE WHEN \"Return Date\" IS NOT NULL AND TRIM(\"Return Date\") <> \'\' AND LOWER(TRIM(\"Return Date\")) <> \'null\' THEN TRY_TO_DOUBLE(\"Selling Price\") ELSE 0 END AS return_sales, CASE WHEN LOWER(\"Sale Order Status\") LIKE \'%cancel%\' OR LOWER(\"Shipping Courier Status\") LIKE \'%cancel%\' THEN 1 ELSE 0 END AS cancelled_quantity, coalesce(sm.product_name,sm1.product_name,usm.product_name,usm1.product_name) as mapped_product_name, upper(coalesce(sm.product_category,sm1.product_category,usm.product_category,usm1.product_category,fi.category)) as mapped_category, upper(coalesce(sm.product_sub_category,sm1.product_sub_category)) as mapped_sub_category, upper(coalesce(sm.commonsku,sm1.commonsku,usm.commonsku,usm1.commonsku)) as commonsku, coalesce(sm.cost,sm1.cost,usm.cost,usm1.cost) as cogs, coalesce(sm.mrp,sm1.mrp,usm.mrp,usm1.mrp) as sku_mrp, upper(coalesce(sm.brand,sm1.brand,usm.brand,usm1.brand)) as brand, coalesce(sm.tax_rate,sm1.tax_rate) as tax_rate, coalesce(sm.packaging_cost,sm1.packaging_cost) as packaging_cost, ROW_NUMBER() OVER ( PARTITION BY \"Display Order Code\", \"Sale Order Item Code\" ORDER BY TRY_TO_TIMESTAMP(NULLIF(updated, \'\')) DESC ) AS rw FROM medmongers_db.MAPLEMONK.medmongers_db_get_sale_orders fi left join ( select channel_sku, upper(sku_code) as commonsku, upper(product_name) as product_name, upper(category) as product_category, upper(sub_category) as product_sub_category, landing_cost as cost, mrp, brand, tax_rate, packaging_cost from medmongers_db.maplemonk.medmongers_final_sku_master qualify row_number() over (partition by channel_sku order by channelname) = 1 ) sm on lower(trim(sm.channel_sku)) = lower(trim(case when upper(marketplace) like \'%PHARMEASY%\' then LTRIM(\"Channel Product Id\", \'0\') else \"Channel Product Id\" end)) left join ( select product_id, upper(sku_code) as commonsku, upper(product_name) as product_name, upper(category) as product_category, upper(sub_category) as product_sub_category, landing_cost as cost, mrp, brand, tax_rate, packaging_cost from medmongers_db.maplemonk.medmongers_final_sku_master qualify row_number() over (partition by product_id order by channelname) = 1 ) sm1 on lower(trim(sm1.product_id)) = lower(trim(case when upper(marketplace) like \'%PHARMEASY%\' then LTRIM(\"Channel Product Id\", \'0\') else \"Channel Product Id\" end)) left join ( select channel_sku, upper(sku_code) as commonsku, upper(product_name) as product_name, upper(category) as product_category, case when cost = \'\' then null else cast(cost as float) end as cost, case when mrp = \'\' then null else cast(mrp as float) end as mrp, brand from medmongers_db.maplemonk.medmongers_unicommerce_sku_master where final_marketplace = \'FLIPKART\' qualify row_number() over (partition by lower(trim(channel_sku)) order by channelname) = 1 ) usm on lower(trim(usm.channel_sku)) = lower(trim(case when upper(marketplace) like \'%PHARMEASY%\' then LTRIM(\"Channel Product Id\", \'0\') else \"Channel Product Id\" end)) left join ( select product_id, upper(sku_code) as commonsku, upper(product_name) as product_name, upper(category) as product_category, case when cost = \'\' then null else cast(cost as float) end cost, case when mrp = \'\' then null else cast(mrp as float) end as mrp, brand from medmongers_db.maplemonk.medmongers_unicommerce_sku_master where final_marketplace = \'FLIPKART\' qualify row_number() over (partition by lower(trim(product_id)) order by channelname) = 1 ) usm1 on lower(trim(usm1.product_id)) = lower(trim(case when upper(marketplace) like \'%PHARMEASY%\' then LTRIM(\"Channel Product Id\", \'0\') else \"Channel Product Id\" end)) ) WHERE rw = 1;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from MEDMONGERS_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            